import csv
power='42493d5e-d7c8-5e7c-b100-a81e5d773b79'
occ='26776421-83f2-518b-9716-873fcaa13a04'
p={}
o={}
for tid,ts,val in list(csv.reader(open(VALUES_CSV)))[1:]:
    if tid==power:
        p[ts]=float(val)
    elif tid==occ:
        o[ts]=float(val)
day='2018-07-23'
pts=[ts for ts in p if ts.startswith(day)]
count=0
mism=0
for ts in pts:
    pv=p[ts]
    ov=o.get(ts)
    if ov is None:
        mism+=1
        continue
    if pv>1 and ov==0:
        count+=1
print('points on day', len(pts))
print('missing occ', mism)
print('count', count)
